pub fn ResolutionStorePathFormatter(comptime SemverIntType: type) type {
    return struct {
        res: ResolutionType(SemverIntType),
        string_buf: []const u8,

pub fn format(self: @This(), writer: *std.Io.Writer) std.Io.Writer.Error!void {
                const string_buf = self.string_buf;
                const res = (if (@typeInfo(@TypeOf(self.res)) == .@"enum") @intFromEnum(self.res) else self.res.value);
                switch (self.res.tag) {
.root => {
_ = try writer.writeAll("root");
},
.npm => {
_ = try writer.print("{f}", .{ res.npm.version.fmt(string_buf) });
},
.local_tarball => {
_ = try writer.print("{f}", .{ res.local_tarball.fmtStorePath(string_buf) });
},
.remote_tarball => {
_ = try writer.print("{f}", .{ res.remote_tarball.fmtStorePath(string_buf) });
},
.folder => {
_ = try writer.print("{f}", .{ res.folder.fmtStorePath(string_buf) });
},
.git => {
_ = try writer.print("{f}", .{ res.git.fmtStorePath("git+", string_buf) });
},
.github => {
_ = try writer.print("{f}", .{ res.github.fmtStorePath("github+", string_buf) });
},
.workspace => {
_ = try writer.print("{f}", .{ res.workspace.fmtStorePath(string_buf) });
},
.symlink => {
_ = try writer.print("{f}", .{ res.symlink.fmtStorePath(string_buf) });
},
.single_file_module => {
_ = try writer.print("{f}", .{ res.single_file_module.fmtStorePath(string_buf) });
},
else => {

},
}
        }
    };
}

pub fn ResolutionURLFormatter(comptime SemverIntType: type) type {
    return struct {
        resolution: *const ResolutionType(SemverIntType),
        buf: []const u8,

pub fn format(formatter: ResolutionURLFormatter(SemverIntType), writer: *std.Io.Writer) std.Io.Writer.Error!void {
                const buf = formatter.buf;
                const value = (if (@typeInfo(@TypeOf(formatter.resolution)) == .@"enum") @intFromEnum(formatter.resolution) else formatter.resolution.value);
                switch (formatter.resolution.tag) {
.npm => {
_ = try writer.writeAll(value.npm.url.slice(formatter.buf));
},
.local_tarball => {
_ = try bun.fmt.fmtPath(u8, value.local_tarball.slice(buf), .{ .path_sep = .posix }).format(writer);
},
.folder => {
_ = try writer.writeAll(value.folder.slice(formatter.buf));
},
.remote_tarball => {
_ = try writer.writeAll(value.remote_tarball.slice(formatter.buf));
},
.git => {
_ = try value.git.formatAs("git+", formatter.buf, writer);
},
.github => {
_ = try value.github.formatAs("github:", formatter.buf, writer);
},
.workspace => {
_ = try writer.print("workspace:{s}", .{ value.workspace.slice(formatter.buf) });
},
.symlink => {
_ = try writer.print("link:{s}", .{ value.symlink.slice(formatter.buf) });
},
.single_file_module => {
_ = try writer.print("module:{s}", .{ value.single_file_module.slice(formatter.buf) });
},
else => {

},
}
        }
    };
}

