pub fn ResolutionType(comptime SemverIntType: type) type {
    return extern struct {
        tag: ResolutionTag = .uninitialized,
        _padding: [7]u8 = @as([7]u8, .{ 0, 0, 0, 0, 0, 0, 0 }),
        value: Value = Value{ .uninitialized = std.mem.zeroes(void) },

pub inline fn init(value: bun.@"meta".Tagged(Value, Tag)) This {
                return .{ .tag = std.@"meta".activeTag(value), .value = Value.init(value) };
        }

pub fn isGit(self: @This()) bool {
                return self.tag.isGit();
        }

pub fn canEnqueueInstallTask(self: @This()) bool {
                return self.tag.canEnqueueInstallTask();
        }

pub fn satisfiesDependencyVersion(self: @This(), version: *const Dependency.Version, version_buf: []const u8, resolution_buf: []const u8) bool {
                if (((self.tag == .npm) and (version.tag == .npm))) {
                    return (if (@typeInfo(@TypeOf(version)) == .@"enum") @intFromEnum(version) else version.value).npm.version.satisfies(self.value.npm.version, version_buf, resolution_buf);
                }
                if (((self.tag == .git) and (version.tag == .git))) {
                    return self.value.git.eql((&(if (@typeInfo(@TypeOf(version)) == .@"enum") @intFromEnum(version) else version.value).git), resolution_buf, version_buf);
                }
                if (((self.tag == .github) and (version.tag == .github))) {
                    return self.value.github.eql((&(if (@typeInfo(@TypeOf(version)) == .@"enum") @intFromEnum(version) else version.value).github), resolution_buf, version_buf);
                }
                return false;
        }

pub fn fromTextLockfile(res_str: []const u8, string_buf: *String.Buf) FromTextLockfileError!This {
                if (strings.hasPrefixComptime(res_str, "root:")) {
                    return This.init(.{ .root = std.mem.zeroes(void) });
                }
                if (strings.withoutPrefixIfPossibleComptime(res_str, "link:")) |link| {
                    _ = &link;
                    return This.init(.{ .symlink = try string_buf.append(link) });
                }
                if (strings.withoutPrefixIfPossibleComptime(res_str, "workspace:")) |workspace| {
                    _ = &workspace;
                    return This.init(.{ .workspace = try string_buf.append(workspace) });
                }
                if (strings.withoutPrefixIfPossibleComptime(res_str, "file:")) |folder| {
                    _ = &folder;
                    return This.init(.{ .folder = try string_buf.append(folder) });
                }
                return (switch (Dependency.Version.Tag.infer(res_str)) {
.git => This.init(.{ .git = try Repository.parseAppendGit(res_str, string_buf) }),
.github => This.init(.{ .github = try Repository.parseAppendGithub(res_str, string_buf) }),
.tarball => {
{
                    if (Dependency.isRemoteTarball(res_str)) {
                        return This.init(.{ .remote_tarball = try string_buf.append(res_str) });
                    }
                    return This.init(.{ .local_tarball = try string_buf.append(res_str) });
                }
},
.npm => {
{
                    const version_literal = try string_buf.append(res_str);
                    const parsed = Semver.Version.parse(version_literal.sliced(string_buf.bytes.items));
                    if ((!parsed.valid)) {
                        return error.UnexpectedResolution;
                    }
                    if ((((parsed.version.major == null) or (parsed.version.minor == null)) or (parsed.version.patch == null))) {
                        return error.UnexpectedResolution;
                    }
                    return .{ .tag = .npm, .value = .{ .npm = .{ .version = parsed.version.min(), .url = .{} } } };
                }
},
.workspace => error.UnexpectedResolution,
.symlink => error.UnexpectedResolution,
.folder => error.UnexpectedResolution,
.catalog => error.UnexpectedResolution,
.dist_tag => error.UnexpectedResolution,
.uninitialized => error.UnexpectedResolution,
});
        }

pub fn fromPnpmLockfile(res_str: []const u8, string_buf: *String.Buf) FromPnpmLockfileError!Resolution {
                if (strings.withoutPrefixIfPossibleComptime(res_str, "https://codeload.github.com/")) |user_repo_tar_committish| {
                    _ = &user_repo_tar_committish;
                    var user_end: usize = 0;
                    _ = &user_end;
                    if (strings.indexOfChar(user_repo_tar_committish, 47)) |ue| {
                        _ = &ue;
                        user_end = ue;
                    } else {
                        return error.InvalidPnpmLockfile;
                    }
                    const user = user_repo_tar_committish[0..user_end];
                    const repo_tar_committish = user_repo_tar_committish[(user_end + 1)..];
                    var repo_end: usize = 0;
                    _ = &repo_end;
                    if (strings.indexOfChar(repo_tar_committish, 47)) |re| {
                        _ = &re;
                        repo_end = re;
                    } else {
                        return error.InvalidPnpmLockfile;
                    }
                    const repo = repo_tar_committish[0..repo_end];
                    const tar_committish = repo_tar_committish[(repo_end + 1)..];
                    var tar_end: usize = 0;
                    _ = &tar_end;
                    if (strings.indexOfChar(tar_committish, 47)) |te| {
                        _ = &te;
                        tar_end = te;
                    } else {
                        return error.InvalidPnpmLockfile;
                    }
                    const committish = tar_committish[(tar_end + 1)..];
                    return This.init(.{ .github = .{ .owner = try string_buf.append(user), .repo = try string_buf.append(repo), .committish = try string_buf.append(committish) } });
                }
                if (strings.withoutPrefixIfPossibleComptime(res_str, "file:")) |path| {
                    _ = &path;
                    if (strings.endsWithComptime(res_str, ".tgz")) {
                        return This.init(.{ .local_tarball = try string_buf.append(path) });
                    }
                    return This.init(.{ .folder = try string_buf.append(path) });
                }
                return (switch (Dependency.Version.Tag.infer(res_str)) {
.git => This.init(.{ .git = try Repository.parseAppendGit(res_str, string_buf) }),
.github => This.init(.{ .github = try Repository.parseAppendGithub(res_str, string_buf) }),
.tarball => {
{
                    if (Dependency.isRemoteTarball(res_str)) {
                        return This.init(.{ .remote_tarball = try string_buf.append(res_str) });
                    }
                    return This.init(.{ .local_tarball = try string_buf.append(res_str) });
                }
},
.npm => {
{
                    const version_literal = try string_buf.append(res_str);
                    const parsed = Semver.Version.parse(version_literal.sliced(string_buf.bytes.items));
                    if ((!parsed.valid)) {
                        return error.InvalidPnpmLockfile;
                    }
                    if ((((parsed.version.major == null) or (parsed.version.minor == null)) or (parsed.version.patch == null))) {
                        return error.InvalidPnpmLockfile;
                    }
                    return This.init(.{ .npm = .{ .version = parsed.version.min(), .url = .{} } });
                }
},
.workspace => error.InvalidPnpmLockfile,
.symlink => error.InvalidPnpmLockfile,
.folder => error.InvalidPnpmLockfile,
.catalog => error.InvalidPnpmLockfile,
.dist_tag => error.InvalidPnpmLockfile,
.uninitialized => error.InvalidPnpmLockfile,
});
        }

pub fn order(lhs: *const This, rhs: *const This, lhs_buf: []const u8, rhs_buf: []const u8) std.math.Order {
                if ((lhs.tag != rhs.tag)) {
                    return std.math.order(@intFromEnum(lhs.tag), @intFromEnum(rhs.tag));
                }
                return (switch (lhs.tag) {
.npm => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).npm.order((if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).npm, lhs_buf, rhs_buf),
.local_tarball => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).local_tarball.order((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).local_tarball), lhs_buf, rhs_buf),
.folder => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).folder.order((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).folder), lhs_buf, rhs_buf),
.remote_tarball => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).remote_tarball.order((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).remote_tarball), lhs_buf, rhs_buf),
.workspace => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).workspace.order((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).workspace), lhs_buf, rhs_buf),
.symlink => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).symlink.order((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).symlink), lhs_buf, rhs_buf),
.single_file_module => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).single_file_module.order((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).single_file_module), lhs_buf, rhs_buf),
.git => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).git.order((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).git), lhs_buf, rhs_buf),
.github => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).github.order((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).github), lhs_buf, rhs_buf),
else => .eq,
});
        }

pub fn count(self: @This(), buf: []const u8, comptime Builder: type, builder: Builder) void {
                switch (self.tag) {
.npm => {
_ = self.value.npm.count(buf, Builder, builder);
},
.local_tarball => {
_ = builder.count(self.value.local_tarball.slice(buf));
},
.folder => {
_ = builder.count(self.value.folder.slice(buf));
},
.remote_tarball => {
_ = builder.count(self.value.remote_tarball.slice(buf));
},
.workspace => {
_ = builder.count(self.value.workspace.slice(buf));
},
.symlink => {
_ = builder.count(self.value.symlink.slice(buf));
},
.single_file_module => {
_ = builder.count(self.value.single_file_module.slice(buf));
},
.git => {
_ = self.value.git.count(buf, Builder, builder);
},
.github => {
_ = self.value.github.count(buf, Builder, builder);
},
else => {

},
}
        }

pub fn clone(self: @This(), buf: []const u8, comptime Builder: type, builder: Builder) This {
                return .{ .tag = self.tag, .value = (switch (self.tag) {
.npm => Value.init(.{ .npm = self.value.npm.clone(buf, Builder, builder) }),
.local_tarball => Value.init(.{ .local_tarball = builder.append(String, self.value.local_tarball.slice(buf)) }),
.folder => Value.init(.{ .folder = builder.append(String, self.value.folder.slice(buf)) }),
.remote_tarball => Value.init(.{ .remote_tarball = builder.append(String, self.value.remote_tarball.slice(buf)) }),
.workspace => Value.init(.{ .workspace = builder.append(String, self.value.workspace.slice(buf)) }),
.symlink => Value.init(.{ .symlink = builder.append(String, self.value.symlink.slice(buf)) }),
.single_file_module => Value.init(.{ .single_file_module = builder.append(String, self.value.single_file_module.slice(buf)) }),
.git => Value.init(.{ .git = self.value.git.clone(buf, Builder, builder) }),
.github => Value.init(.{ .github = self.value.github.clone(buf, Builder, builder) }),
.root => Value.init(.{ .root = std.mem.zeroes(void) }),
.uninitialized => Value.init(.{ .uninitialized = std.mem.zeroes(void) }),
else => std.debug.panic("Internal error: unexpected resolution tag: {}", .{ self.tag }),
}) };
        }

pub fn copy(self: @This()) Resolution {
                return (switch (self.tag) {
.npm => .init(.{ .npm = self.value.npm }),
.local_tarball => .init(.{ .local_tarball = self.value.local_tarball }),
.folder => .init(.{ .folder = self.value.folder }),
.remote_tarball => .init(.{ .remote_tarball = self.value.remote_tarball }),
.workspace => .init(.{ .workspace = self.value.workspace }),
.symlink => .init(.{ .symlink = self.value.symlink }),
.single_file_module => .init(.{ .single_file_module = self.value.single_file_module }),
.git => .init(.{ .git = self.value.git }),
.github => .init(.{ .github = self.value.github }),
.root => .init(.{ .root = std.mem.zeroes(void) }),
.uninitialized => .init(.{ .uninitialized = std.mem.zeroes(void) }),
else => std.debug.panic("Internal error: unexpected resolution tag: {}", .{ self.tag }),
});
        }

pub fn fmt(self: *const @This(), string_bytes: []const u8, path_sep: bun.fmt.PathFormatOptions.Sep) Formatter {
                return Formatter{ .resolution = self, .buf = string_bytes, .path_sep = path_sep };
        }

pub fn fmtStorePath(self: @This(), string_buf: []const u8) StorePathFormatter {
                return .{ .res = self, .string_buf = string_buf };
        }

pub fn fmtURL(self: *const @This(), string_bytes: []const u8) URLFormatter {
                return URLFormatter{ .resolution = self, .buf = string_bytes };
        }

pub fn fmtForDebug(this_ptr: *const This, string_bytes: []const u8) DebugFormatter {
                return DebugFormatter{ .resolution = this_ptr, .buf = string_bytes };
        }

pub fn eql(lhs: *const This, rhs: *const This, lhs_string_buf: []const u8, rhs_string_buf: []const u8) bool {
                if ((lhs.tag != rhs.tag)) {
                    return false;
                }
                return (switch (lhs.tag) {
.root => true,
.npm => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).npm.eql((if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).npm),
.local_tarball => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).local_tarball.eql((if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).local_tarball, lhs_string_buf, rhs_string_buf),
.folder => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).folder.eql((if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).folder, lhs_string_buf, rhs_string_buf),
.remote_tarball => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).remote_tarball.eql((if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).remote_tarball, lhs_string_buf, rhs_string_buf),
.workspace => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).workspace.eql((if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).workspace, lhs_string_buf, rhs_string_buf),
.symlink => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).symlink.eql((if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).symlink, lhs_string_buf, rhs_string_buf),
.single_file_module => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).single_file_module.eql((if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).single_file_module, lhs_string_buf, rhs_string_buf),
.git => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).git.eql((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).git), lhs_string_buf, rhs_string_buf),
.github => (if (@typeInfo(@TypeOf(lhs)) == .@"enum") @intFromEnum(lhs) else lhs.value).github.eql((&(if (@typeInfo(@TypeOf(rhs)) == .@"enum") @intFromEnum(rhs) else rhs.value).github), lhs_string_buf, rhs_string_buf),
else => unreachable,
});
        }
        const This = @This();
        pub const StorePathFormatter = ResolutionStorePathFormatter(SemverIntType);
        pub const URLFormatter = ResolutionURLFormatter(SemverIntType);
        pub const Formatter = ResolutionFormatter(SemverIntType);
        pub const DebugFormatter = ResolutionDebugFormatter(SemverIntType);
        pub const Value = ResolutionValue(SemverIntType);
        pub const Tag = ResolutionTag;
        const FromTextLockfileError = (OOM || error{
                UnexpectedResolution,
                InvalidSemver,
            });
        const FromPnpmLockfileError = (OOM || error{InvalidPnpmLockfile});
    };
}

pub const Resolution = ResolutionType(u64);
pub const OldV2Resolution = ResolutionType(u32);
const string = []const u8;
const OOM = bun.OOM;
const strings = bun.strings;
const Dependency = bun.install.Dependency;
const Semver = bun.Semver;
const String = Semver.String;

pub fn initResolutionValue(comptime ValueT: type, comptime TagT: type, field: bun.@"meta".Tagged(ValueT, TagT)) ValueT {
        var value = ValueT.zero;
        _ = &value;
        switch (field) {
.uninitialized, .root => {

},
.npm => |v| {
value.npm = v;
},
.folder => |v| {
value.folder = v;
},
.local_tarball => |v| {
value.local_tarball = v;
},
.github => |v| {
value.github = v;
},
.git => |v| {
value.git = v;
},
.symlink => |v| {
value.symlink = v;
},
.workspace => |v| {
value.workspace = v;
},
.remote_tarball => |v| {
value.remote_tarball = v;
},
.single_file_module => |v| {
value.single_file_module = v;
},
}
        return value;
}
